# Define the grid world with the goal located in the bottom right corner
grid = [
    [0, 2, 4],
    [1, 'X', 6],
    [3, 5, 7]
]

def get_adjacent_states(state):
    """Return a list of adjacent states to the given state"""
    x, y = state
    adjacent_states = []

    # Check all four directions (up, down, left, right)
    for dx, dy in [(0, -1), (0, 1), (-1, 0), (1, 0)]:
        new_x, new_y = x + dx, y + dy

        # Ensure the new position is within the grid boundaries
        if 0 <= new_x < len(grid) and 0 <= new_y < len(grid[0]):
            adjacent_states.append((new_x, new_y))

    return adjacent_states

def get_state_value(state):
    """Return the value of a state (1 for goal state, 0 otherwise)"""
    x, y = state
    if x == len(grid) - 1 and y == len(grid[0]) - 1:
        return 1
    else:
        return 0

# Group states based on their values
state_groups = {}
for i in range(len(grid)):
    for j in range(len(grid[0])):
        state_value = get_state_value((i, j))
        if state_value not in state_groups:
            state_groups[state_value] = []
        state_groups[state_value].append((i, j))

# Print the grouped states
print(list(state_groups.values()))
